<script>
  import { init } from '../../utils'
  import { tabpanels } from './tabs.svelte.js'

  const { id = null, class: klass = '', children, ...rest } = $props()

  init(() => {
    if (!id) throw new Error('Tabpanels must have an id')
  })
</script>

<div {...rest} {id} class="tabpanels {klass}" use:tabpanels>
  {#if children}
    {@render children()}
  {/if}
</div>
